const body = $json.body || $json;
const name = (body.name || '').trim();
const email = (body.email || '').trim();
const companySize = body.company_size || '';
const pain = (body.pain || '').trim();

if (!name || !email || !companySize) {
  throw new Error('Missing required fields: name, email, or company_size');
}

const lead = {
  name: name,
  email: email,
  companySize: companySize,
  pain: pain,
  source: 'sme.riera.co.uk',
  receivedAt: new Date().toISOString()
};

const chatId = 'REPLACE_CHAT_ID';

const telegramText = [
  '\u{1f4e5} New lead from website',
  '',
  'Name: ' + lead.name,
  'Email: ' + lead.email,
  'Company size: ' + lead.companySize,
  'Pain: ' + (lead.pain || '(not provided)'),
  '',
  'Source: ' + lead.source,
  'Time: ' + lead.receivedAt
].join('\n');

return {
  json: {
    ...lead,
    chatId: chatId,
    telegramText: telegramText
  }
};
